const tri = (ru: string, uk: string, es: string, planned: Partial<Record<keyof typeof PLANNED_LOCALE_FALLBACK, string>> = {}): TriText => {
  return {
    ru,
    uk,
    es,
  'pt-BR': planned['pt-BR'] ?? PLANNED_LOCALE_FALLBACK['pt-BR'],
  vi: planned.vi ?? PLANNED_LOCALE_FALLBACK.vi,
  id: planned.id ?? PLANNED_LOCALE_FALLBACK.id,
  tr: planned.tr ?? PLANNED_LOCALE_FALLBACK.tr,
  pl: planned.pl ?? PLANNED_LOCALE_FALLBACK.pl,
  };
};

function pronounStep(input: {
  id: string;
  order: number;
  difficulty: DiagnosisTrainingStep['difficulty'];
  targetSkill: string;
  sentence: string;
  translation: TriText;
  options: string[];
  correctAnswer: string;
  correctFeedback: TriText;
  wrong: Record<string, TriText>;
  retry: [TriText, TriText, TriText];
  focusWords: string[];
}): DiagnosisTrainingStep {
  const correctIndex = input.options.findIndex((option) => option === input.correctAnswer);
  return {
    id: input.id,
    order: input.order,
    difficulty: input.difficulty,
    type: 'single_choice',
    targetSkill: input.targetSkill,
    translation: input.translation,
    explanationBlock: tri(
      'Сначала найди роль местоимения. Кто делает действие: I, he, she, we, they. Кого действие касается или кто стоит после предлога: me, him, her, us, them.',
      'Спочатку знайди роль займенника. Хто виконує дію: I, he, she, we, they. Кого дія стосується або хто стоїть після прийменника: me, him, her, us, them.',
      'Primero encuentra el papel del pronombre. Quien hace la acción usa subject form: I, he, she, we, they. Después de verbo o preposición usamos object form: me, him, her, us, them.',
      {
        'pt-BR': 'Primeiro encontre o papel do pronome. Quem faz a ação: I, he, she, we, they. Quem recebe a ação ou vem depois de preposição: me, him, her, us, them.',
        vi: 'Trước tiên hãy tìm vai trò của đại từ. Ai làm hành động: I, he, she, we, they. Ai nhận hành động hoặc đứng sau giới từ: me, him, her, us, them.',
        id: 'Pertama cari peran pronomina. Siapa yang melakukan aksi: I, he, she, we, they. Siapa yang terkena aksi atau berada setelah preposisi: me, him, her, us, them.',
        tr: 'Önce zamirin rolünü bul. Eylemi kim yapıyor: I, he, she, we, they. Eylem kimi etkiliyor veya edattan sonra kim var: me, him, her, us, them.',
        pl: 'Najpierw znajdź rolę zaimka. Kto wykonuje czynność: I, he, she, we, they. Kogo dotyczy czynność albo kto stoi po przyimku: me, him, her, us, them.',
      },
    ),
    microTask: tri(
      'Выбери местоимение по роли в предложении.',
      'Обери займенник за роллю в реченні.',
      'Elige el pronombre según su papel en la frase.',
      {
        'pt-BR': 'Escolha o pronome de acordo com seu papel na frase.',
        vi: 'Chọn đại từ theo vai trò của nó trong câu.',
        id: 'Pilih pronomina berdasarkan perannya dalam kalimat.',
        tr: 'Cümledeki rolüne göre zamiri seç.',
        pl: 'Wybierz zaimek według jego roli w zdaniu.',
      },
    ),
    sentence: input.sentence,
    answerOptions: input.options.map((text) => ({ id: text, text })),
    correctAnswerId: input.correctAnswer,
    correctIndex,
    correctFeedback: input.correctFeedback,
    wrongFeedbackByOption: Object.fromEntries(input.options
      .filter((option) => option !== input.correctAnswer)
      .map((option) => [option, input.wrong[option] ?? tri(
        'Не совсем. Проверь роль: это местоимение делает действие или получает действие после глагола/предлога?',
        'Не зовсім. Перевір роль: цей займенник виконує дію чи отримує дію після дієслова/прийменника?',
        'No exactamente. Revisa el papel: el pronombre hace la acción o recibe la acción después de verbo/preposición?',
        {
          'pt-BR': 'Não exatamente. Verifique o papel: este pronome faz a ação ou recebe a ação depois de verbo/preposição?',
          vi: 'Chưa hẳn. Kiểm tra vai trò: đại từ này làm hành động hay nhận hành động sau động từ/giới từ?',
          id: 'Belum tepat. Periksa perannya: pronomina ini melakukan aksi atau menerima aksi setelah verba/preposisi?',
          tr: 'Tam değil. Rolü kontrol et: bu zamir eylemi yapıyor mu, yoksa fiil/edat sonrasında eylemi mi alıyor?',
          pl: 'Nie całkiem. Sprawdź rolę: czy ten zaimek wykonuje czynność, czy odbiera czynność po czasowniku/przyimku?',
        },
      )])),
    retryFeedback: [
      input.retry[0],
      input.retry[1],
      input.retry[2],
      tri(
        `Подсказка: правильная форма здесь - "${input.correctAnswer}".`,
        `Підказка: правильна форма тут - "${input.correctAnswer}".`,
        `Pista: la forma correcta aquí es "${input.correctAnswer}".`,
        {
          'pt-BR': `Dica: a forma correta aqui é "${input.correctAnswer}".`,
          vi: `Gợi ý: dạng đúng ở đây là "${input.correctAnswer}".`,
          id: `Petunjuk: bentuk yang benar di sini adalah "${input.correctAnswer}".`,
          tr: `İpucu: burada doğru biçim "${input.correctAnswer}".`,
          pl: `Podpowiedź: poprawna forma tutaj to "${input.correctAnswer}".`,
        },
      ),
    ],
    fallbackExplanation: tri(
      'Остановись и спроси: кто делает действие? Тогда I/he/she/we/they. Кого трогает действие или что стоит после предлога? Тогда me/him/her/us/them.',
      'Зупинись і запитай: хто виконує дію? Тоді I/he/she/we/they. Кого зачіпає дія або що стоїть після прийменника? Тоді me/him/her/us/them.',
      'Detente y pregunta: quién hace la acción? Entonces I/he/she/we/they. A quién afecta la acción o qué va después de preposición? Entonces me/him/her/us/them.',
      {
        'pt-BR': 'Pare e pergunte: quem faz a ação? Então I/he/she/we/they. Quem a ação afeta ou o que vem depois de preposição? Então me/him/her/us/them.',
        vi: 'Dừng lại và hỏi: ai làm hành động? Khi đó dùng I/he/she/we/they. Hành động tác động đến ai hoặc sau giới từ là gì? Khi đó dùng me/him/her/us/them.',
        id: 'Berhenti dan tanyakan: siapa yang melakukan aksi? Maka I/he/she/we/they. Siapa yang terkena aksi atau apa yang berada setelah preposisi? Maka me/him/her/us/them.',
        tr: 'Dur ve sor: eylemi kim yapıyor? O zaman I/he/she/we/they. Eylem kimi etkiliyor veya edattan sonra ne var? O zaman me/him/her/us/them.',
        pl: 'Zatrzymaj się i zapytaj: kto wykonuje czynność? Wtedy I/he/she/we/they. Kogo dotyczy czynność albo co stoi po przyimku? Wtedy me/him/her/us/them.',
      },
    ),
    focusWords: input.focusWords,
  };
}

